// newAuthSetupCmd prints concrete steps for getting a credential. Side-effect
// rule: print by default, --launch opt-in to open the URL, short-circuit when
// the verifier is running this in a sandboxed subprocess.
func newAuthSetupCmd(_ *rootFlags) *cobra.Command {
	var launch bool
	cmd := &cobra.Command{
		Use:     "setup",
		Short:   "Print steps for obtaining a credential (use --launch to open the URL)",
		Example: "  flow-pp-cli auth setup\n  flow-pp-cli auth setup --launch",
		RunE: func(cmd *cobra.Command, args []string) error {
			w := cmd.OutOrStdout()
			fmt.Fprintln(w, "See API docs: https://aisandbox-pa.googleapis.com")
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "Then set:")
			fmt.Fprintln(w, "  export FLOW_SESSION_TOKEN=\"your-token-here\"")
			if !launch {
				return nil
			}
			launchURL := "https://aisandbox-pa.googleapis.com"
			if cliutil.IsVerifyEnv() {
				fmt.Fprintf(w, "would launch: %s\n", launchURL)
				return nil
			}
			if err := openSetupURL(launchURL); err != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "could not open browser automatically: %v\nopen this URL manually: %s\n", err, launchURL)
			}
			return nil
		},
	}
	cmd.Flags().BoolVar(&launch, "launch", false, "Open the setup URL in your default browser")
	return cmd
}

func newAuthLoginCmd(flags *rootFlags) *cobra.Command {
	var cookiesFile string
	cmd := &cobra.Command{
		Use:     "login",
		Short:   "Import a browser session for the session handshake",
		Example: "  flow-pp-cli auth login --cookies-file storage-state.json",
		RunE: func(cmd *cobra.Command, args []string) error {
			w := cmd.OutOrStdout()
			if strings.TrimSpace(cookiesFile) == "" {
				fmt.Fprintln(w, "Import browser-session cookies from Playwright storage-state JSON or a raw Cookie header file:")
				fmt.Fprintf(w, "  flow-pp-cli auth login --cookies-file storage-state.json\n")
				return nil
			}
			// Flow has two independent auth surfaces (see
			// .printing-press-patches/2026-08-30-nextauth-cookie-surface.md):
			// aisandbox-pa.googleapis.com (credits, video status) takes the
			// harvested ya29.* Bearer token via FLOW_SESSION_TOKEN, unrelated to
			// cookies. labs.google's own tRPC BFF (project/projects/scenes gaps/
			// drive import --tag-scene) is gated by a NextAuth session cookie
			// instead -- that's what --cookies-file is actually for, so imports
			// are scoped to labs.google, not aisandbox-pa.googleapis.com.
			imported, err := loadSessionCookiesFromFile(cookiesFile, "labs.google", nextAuthCookieNames)
			if err != nil {
				return authErr(err)
			}
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}
			c := client.New(cfg, flags.timeout, flags.rateLimit)
			if c.Session == nil {
				return authErr(fmt.Errorf("session handshake manager is not configured"))
			}
			if err := c.Session.ImportSession("https://labs.google", imported, ""); err != nil {
				return authErr(err)
			}
			fmt.Fprintf(w, "%s Imported browser-session cookies for labs.google.\n", green("OK"))
			fmt.Fprintln(w, "This unlocks project, projects, scenes gaps, and drive import --tag-scene.")
			fmt.Fprintln(w, "(sync --resources projects and export projects still don't work -- a")
			fmt.Fprintln(w, "separate, unrelated gap; use the projects command directly instead.)")
			fmt.Fprintln(w, "It does NOT cover credits, video watch, or generation -- those need the")
			fmt.Fprintln(w, "separate ya29.* Bearer token, captured from your browser's network tab")
			fmt.Fprintln(w, "(the Authorization header on any aisandbox-pa.googleapis.com request)")
			fmt.Fprintln(w, "and set via FLOW_SESSION_TOKEN. Neither credential auto-refreshes;")
			fmt.Fprintln(w, "re-run auth login / re-export FLOW_SESSION_TOKEN when either expires.")
			return nil
		},
	}
	cmd.Flags().StringVar(&cookiesFile, "cookies-file", "", "Import cookies from a Playwright storage-state JSON file or raw Cookie header file")
	return cmd
}

// jsonCookieEntry matches both Playwright storage-state's per-cookie shape
// and the bare-array shape several other capture tools emit (Puppeteer's
// page.cookies(), browser-use's `cookies export`, most DevTools-cookie
// browser extensions) -- same field names, just not wrapped in {"cookies":[...]}.
type jsonCookieEntry struct {
	Name     string  `json:"name"`
	Value    string  `json:"value"`
	Domain   string  `json:"domain"`
	Path     string  `json:"path"`
	Expires  float64 `json:"expires"`
	Secure   bool    `json:"secure"`
	HTTPOnly bool    `json:"httpOnly"`
}

// nextAuthCookieNames is the exact allowlist of cookies this CLI's
// labs.google auth surface actually needs. A storage-state export of a real
// browser session for this domain also carries app-specific cookies with no
// bearing on auth -- notably `email`/`EMAIL` (the user's own email address)
// and Google Analytics `_ga*` cookies -- which importing indiscriminately
// would persist to session.json for no functional benefit. See
// .printing-press-patches/2026-08-30-nextauth-cookie-surface.md.
var nextAuthCookieNames = []string{
	"__Secure-next-auth.session-token",
	"__Host-next-auth.csrf-token",
	"__Secure-next-auth.callback-url",
}

func sessionCookieNameAllowed(name string, allowed []string) bool {
	if len(allowed) == 0 {
		return true
	}
	for _, a := range allowed {
		if name == a {
			return true
		}
	}
	return false
}

func loadSessionCookiesFromFile(path string, domain string, allowedNames []string) ([]*http.Cookie, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("reading cookies file: %w", err)
	}
	var entries []jsonCookieEntry
	var state struct {
		Cookies []jsonCookieEntry `json:"cookies"`
	}
	// Try Playwright's storage-state shape ({"cookies":[...]}) first, then
	// fall back to a bare top-level array (Puppeteer, browser-use, most
	// DevTools cookie-export extensions) before giving up on JSON entirely.
	if err := json.Unmarshal(data, &state); err == nil {
		entries = state.Cookies
	} else if err := json.Unmarshal(data, &entries); err != nil {
		entries = nil
	}
	if entries != nil {
		if len(entries) == 0 {
			return nil, fmt.Errorf("cookies file contains an empty cookies array")
		}
		cookies := make([]*http.Cookie, 0, len(entries))
		for _, c := range entries {
			if !sessionCookieDomainMatches(c.Domain, domain) {
				continue
			}
			name := strings.TrimSpace(c.Name)
			if name == "" {
				continue
			}
			if !sessionCookieNameAllowed(name, allowedNames) {
				continue
			}
			path := c.Path
			if path == "" {
				path = "/"
			}
			ck := &http.Cookie{Name: name, Value: c.Value, Domain: c.Domain, Path: path, Secure: c.Secure, HttpOnly: c.HTTPOnly}
			if c.Expires > 0 {
				ck.Expires = time.Unix(int64(c.Expires), 0)
			}
			cookies = append(cookies, ck)
		}
		if len(cookies) == 0 {
			return nil, fmt.Errorf("cookies file contains no cookies for %s", domain)
		}
		return cookies, nil
	}
	header := trimSessionCookieHeaderPrefix(string(data))
	cookies := parseSessionCookieHeaderCookies(header, allowedNames)
	if len(cookies) == 0 {
		return nil, fmt.Errorf("cookies file is empty")
	}
	return cookies, nil
}

func trimSessionCookieHeaderPrefix(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= len("Cookie:") && strings.EqualFold(s[:len("Cookie:")], "Cookie:") {
		return strings.TrimSpace(s[len("Cookie:"):])
	}
	return s
}

func parseSessionCookieHeaderCookies(header string, allowedNames []string) []*http.Cookie {
	parts := strings.Split(header, ";")
	cookies := make([]*http.Cookie, 0, len(parts))
	for _, part := range parts {
		name, value, ok := strings.Cut(strings.TrimSpace(part), "=")
		if !ok || strings.TrimSpace(name) == "" {
			continue
		}
		name = strings.TrimSpace(name)
		if !sessionCookieNameAllowed(name, allowedNames) {
			continue
		}
		cookies = append(cookies, &http.Cookie{Name: name, Value: strings.TrimSpace(value), Path: "/"})
	}
	return cookies
}

func sessionCookieDomainMatches(cookieDomain string, targetDomain string) bool {
	target := strings.TrimPrefix(strings.ToLower(strings.TrimSpace(targetDomain)), ".")
	if target == "" {
		return true
	}
	candidate := strings.TrimPrefix(strings.ToLower(strings.TrimSpace(cookieDomain)), ".")
	return candidate == target || strings.HasSuffix(candidate, "."+target) || (strings.Contains(candidate, ".") && strings.HasSuffix(target, "."+candidate))
}

// openSetupURL opens url in the OS default browser. Per the side-effect rule,
// the caller short-circuits with cliutil.IsVerifyEnv() before this is reached.
func openSetupURL(url string) error {
	var c *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		c = exec.Command("open", url)
	case "linux":
		c = exec.Command("xdg-open", url)
	case "windows":
		c = exec.Command("rundll32", "url.dll,FileProtocolHandler", url)
	default:
		return fmt.Errorf("unsupported OS: %s", runtime.GOOS)
	}
	return c.Start()
}

func newAuthStatusCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:     "status",
		Short:   "Show authentication status",
		Example: "  flow-pp-cli auth status",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			w := cmd.OutOrStdout()
			header := cfg.AuthHeader()
			authed := header != ""
			refusals := cfg.CredentialRefusalSummaries()
			credentialRefused := len(refusals) > 0
			// Flow has two independent auth surfaces (see
			// .printing-press-patches/2026-08-30-nextauth-cookie-surface.md):
			// AuthHeader() above covers only the ya29.* Bearer token
			// (aisandbox-pa.googleapis.com: credits, video, generation).
			// labs.google's own tRPC BFF (project/projects/scenes gaps/drive
			// import --tag-scene/sync --resources projects) needs a separate
			// NextAuth session cookie instead, imported via
			// `auth login --cookies-file`; report on it independently so
			// neither surface's absence is mistaken for the other's.
			labsGoogleSession := false
			if c := client.New(cfg, flags.timeout, flags.rateLimit); c.Session != nil {
				labsGoogleSession = c.Session.HasCookieFor("https://labs.google/", "__Secure-next-auth.session-token")
			}
			// JSON envelope: {authenticated, verified, source, config}. When not
			// authenticated, write the envelope first then return authErr
			// so exit code carries the auth-failure signal.
			if flags.asJSON {
				out := map[string]any{
					"authenticated":       authed,
					"verified":            false,
					"source":              cfg.AuthSource,
					"config":              cfg.Path,
					"labs_google_session": labsGoogleSession,
				}
				if credentialRefused {
					out["credential_refused"] = true
					out["credential_refusals"] = refusals
				}
				if printErr := printJSONFiltered(w, out, flags); printErr != nil {
					return printErr
				}
				if !authed && !labsGoogleSession && credentialRefused {
					return authErr(cfg.CredentialRefusalError())
				}
				if !authed && !labsGoogleSession {
					return authErr(fmt.Errorf("no credentials configured"))
				}
				return nil
			}
			if !authed && !labsGoogleSession && credentialRefused {
				fmt.Fprintln(w, red("Credentials present but refused"))
				for _, refusal := range refusals {
					fmt.Fprintf(w, "  %s\n", refusal)
				}
				return authErr(cfg.CredentialRefusalError())
			}
			if !authed && !labsGoogleSession {
				fmt.Fprintln(w, red("Not authenticated"))
				fmt.Fprintln(w, "")
				fmt.Fprintln(w, "Neither auth surface has credentials. Set the Bearer token:")
				fmt.Fprintln(w, "  export FLOW_SESSION_TOKEN=\"your-token-here\"")
				fmt.Fprintln(w, "and/or import a labs.google session cookie:")
				fmt.Fprintln(w, "  flow-pp-cli auth login --cookies-file storage-state.json")
				return authErr(fmt.Errorf("no credentials configured"))
			}

			fmt.Fprintln(w, green("Credentials present (not verified)"))
			if authed {
				fmt.Fprintf(w, "  Bearer token: yes (source: %s)\n", cfg.AuthSource)
			} else {
				fmt.Fprintln(w, "  Bearer token: no -- credits/video/generation will fail")
			}
			if labsGoogleSession {
				fmt.Fprintln(w, "  labs.google session cookie: yes")
			} else {
				fmt.Fprintln(w, "  labs.google session cookie: no -- project/projects/scenes gaps/drive import --tag-scene will fail")
			}
			fmt.Fprintf(w, "  Config: %s\n", cfg.Path)
			return nil
		},
	}
}

func credentialSavePath(cfg *config.Config) string {
	if cfg != nil && cfg.AgentcookieManagedByExternalStore() {
		return cfg.Path
	}
	if path, err := cliutil.CredentialsFilePath(); err == nil {
		return path
	}
	if cfg != nil {
		return cfg.Path
	}
	return ""
}

func newAuthLogoutCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:     "logout",
		Short:   "Clear stored credentials",
		Example: "  flow-pp-cli auth logout",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			if err := cfg.ClearTokens(); err != nil {
				return configErr(fmt.Errorf("clearing tokens: %w", err))
			}

			// Identify which (if any) auth env var is still exported so the
			// JSON envelope and the human prose can both surface it.
			envStillSet := ""
			if envStillSet == "" && os.Getenv("FLOW_SESSION_TOKEN") != "" {
				envStillSet = "FLOW_SESSION_TOKEN"
			}

			// JSON envelope: {cleared: true, note?: "<env_var> env var is still set"}.
			if flags.asJSON {
				out := map[string]any{"cleared": true}
				if envStillSet != "" {
					out["note"] = envStillSet + " env var is still set"
				}
				return printJSONFiltered(cmd.OutOrStdout(), out, flags)
			}

			if envStillSet != "" {
				fmt.Fprintf(cmd.OutOrStdout(), "Config cleared. Note: %s env var is still set.\n", envStillSet)
				return nil
			}
			fmt.Fprintln(cmd.OutOrStdout(), "Logged out. Credentials cleared.")
			return nil
		},
	}
}
